39	bool Test::run_tests(const std::string& prefix_) {
40	
41		std::string prefix = to_lower(prefix_);
42		auto& tests = get_tests();
43	
44		// count the number of tests to run:
45		uint32_t to_run = 0;
46		for (auto& test : tests) {
47			if (test.first.find(prefix) != std::string::npos) {
48				++to_run;
49			}
50		}
51	
52		// run the tests:
53		uint32_t passed = 0;
54		uint32_t failed = 0;
55		uint32_t ignored = 0;
56	
57		log("\nRunning %d tests including '%s':\n\n", to_run, prefix.c_str());
58		for (auto& test : tests) {
59			if (test.first.find(prefix) != std::string::npos) {
60				log("\033[0;37m[%d/%d] \033[0;1m%s\033[0m...", passed + failed + 1, to_run,
61				    test.first.c_str());
62				try {
63					test.second();
64					log(" \033[32mPASSED\033[0m\n");
65					passed += 1;
66				} catch (Test::error& e) {
67					log(" \033[31;1mFAILED\n    %s\033[0m\n", e.what());
68					failed += 1;
69				} catch (Test::ignored& e) {
70					log(" \033[33;1mIGNORED\n    %s\033[0m\n", e.what());
71					ignored += 1;
72				}
73			}
74		}
75		log("\n");
76		if (passed || !failed) {
77			log("\033[32mPASSED %d tests.\033[0m\n", passed);
78		}
79		if (failed) {
80			log("\033[31;1mFAILED %d tests.\033[0m\n", failed);
81		}
82		if (ignored) {
83			log("\033[33;1mIGNORED %d tests.\033[0m\n", ignored);
84		}
85		log("\n");
86	
87		return failed == 0;
88	}
