90	std::string Test::mesh_to_string(const Halfedge_Mesh& mesh) {
91	
92		std::stringstream ss;
93		std::unordered_map<uint32_t, uint32_t> vertex_id_to_idx;
94	
95		uint32_t i = 0;
96		for (auto v = mesh.vertices.begin(); v != mesh.vertices.end(); ++v) {
97			vertex_id_to_idx[v->id] = i++;
98		}
99	
100		ss << "Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces({";
101		for (auto v = mesh.vertices.begin(); v != mesh.vertices.end(); ++v) {
102			auto format = [](float val) -> std::string {
103				std::string ret = std::to_string(val);
104				if (ret.find('.') == std::string::npos) ret = ret + ".0f";
105				else ret += "f";
106				return ret;
107			};
108			ss << "Vec3{" << format(v->position.x) << "," << format(v->position.y) << "," << format(v->position.z) << "}";
109			if (v != std::prev(mesh.vertices.end())) {
110				ss << ", ";
111			}
112		}
113		ss << "}, {";
114		bool first = true;
115		for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
116			if (f->boundary) continue;
117			if (!first) ss << ",";
118			first = false;
119			ss << "{";
120			auto h = f->halfedge;
121			do {
122				ss << vertex_id_to_idx[h->vertex->id];
123				h = h->next;
124				if (h != f->halfedge) {
125					ss << ", ";
126				}
127			} while (h != f->halfedge);
128			ss << "}";
129		}
130		ss << "});";
131	
132		return ss.str();
133	}
