135	template<typename T>
136	static std::pair<float, float> time_op(T& _small, T& _large, const std::function<void(T&)>& op) {
137	
138		constexpr uint32_t rounds = 5;
139	
140		float small_time = std::numeric_limits<float>::infinity(),
141			  large_time = std::numeric_limits<float>::infinity();
142	
143		std::vector<T> smalls, larges;
144		for (uint32_t round = 0; round < rounds; round++) {
145			smalls.push_back(_small.copy());
146			larges.push_back(_large.copy());
147		}
148	
149		for (uint32_t round = 0; round < rounds; round++) {
150			{
151				Timer large_t;
152				op(larges[round]);
153				large_time = std::min(large_time, large_t.ms());
154			}
155			{
156				Timer small_t;
157				op(smalls[round]);
158				small_time = std::min(small_time, small_t.ms());
159			}
160		}
161	
162		return std::make_pair(small_time, large_time);
163	}
