165	void Test::check_constant_time(std::function<void(Halfedge_Mesh&)> op) {
166		static Halfedge_Mesh _small = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 0));
167		static Halfedge_Mesh _large = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 4));
168	
169		auto [small_time, large_time] = time_op(_small, _large, op);
170	
171		constexpr float factor = 10.0f;
172		if (factor * small_time < large_time) {
173			throw Test::error("Operation not constant time. Small mesh: " + std::to_string(small_time) +
174			                  "ms vs. Large mesh: " + std::to_string(large_time) + "ms.");
175		}
176	}
