178	void Test::check_linear_time(std::function<void(Halfedge_Mesh&)> op) {
179		static Halfedge_Mesh _small = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 1));
180		static Halfedge_Mesh _large = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 4));
181	
182		auto [small_time, large_time] = time_op(_small, _large, op);
183	
184		size_t small_total_elements = _small.vertices.size() + _small.edges.size() + _small.faces.size();
185		size_t large_total_elements = _large.vertices.size() + _large.edges.size() + _large.faces.size();
186		float ratio =
187			static_cast<float>(large_total_elements) / static_cast<float>(small_total_elements);
188	
189		constexpr float factor = 2.0f;
190		if (factor * ratio * small_time < large_time) {
191			throw Test::error("Operation not linear time. Small mesh: " + std::to_string(small_time) +
192			                  "ms vs. Large mesh: " + std::to_string(large_time) + "ms.");
193		}
194	}
