196	void Test::check_loglinear_time(std::function<void(Indexed_Mesh&)> op) {
197		static Indexed_Mesh _small = Util::closed_sphere_mesh(1.0f, 1);
198		static Indexed_Mesh _large = Util::closed_sphere_mesh(1.0f, 4);
199	
200		auto [small_time, large_time] = time_op(_small, _large, op);
201	
202		float small = static_cast<float>(_small.vertices().size());
203		float large = static_cast<float>(_large.vertices().size());
204	
205		float ratio = (large * std::log2(large)) / (small * std::log2(small));
206	
207		constexpr float factor = 2.0f;
208		if (factor * ratio * small_time < large_time) {
209			throw Test::error(
210				"Operation not log-linear time. Small mesh: " + std::to_string(small_time) +
211				"ms vs. Large mesh: " + std::to_string(large_time) + "ms.");
212		}
213	}
