215	void Test::check_log_time(std::function<void(PT::Tri_Mesh&)> op) {
216		static PT::Tri_Mesh _small = PT::Tri_Mesh(Util::closed_sphere_mesh(1.0f, 1), true);
217		static PT::Tri_Mesh _large = PT::Tri_Mesh(Util::closed_sphere_mesh(1.0f, 4), true);
218	
219		auto [small_time, large_time] = time_op(_small, _large, op);
220	
221		float small = static_cast<float>(_small.n_triangles());
222		float large = static_cast<float>(_large.n_triangles());
223	
224		float ratio = std::log2(large) / std::log2(small);
225	
226		constexpr float factor = 5.0f;
227		if (factor * ratio * small_time < large_time) {
228			throw Test::error(
229				"Operation not log time. Small mesh: " + std::to_string(small_time) +
230				"ms vs. Large mesh: " + std::to_string(large_time) + "ms.");
231		}
232	}
