234	double Test::total_squared_error(const std::vector<double>& a, const std::vector<double>& b) {
235		assert(a.size() == b.size());
236		double error = 0.0;
237		for (uint32_t i = 0; i < a.size(); ++i) {
238			if (a[i] == 0.0) continue;
239			double e = a[i] - b[i];
240			error += e * e / a[i];
241		}
242		return error;
243	}
