245	double Test::total_squared_error(Spectrum a, Spectrum b) {
246		double error = 0.0;
247		for (uint32_t i = 0; i < 3; ++i) {
248			if (a[i] == 0.0) continue;
249			double e = a[i] - b[i];
250			error += e * e / a[i];
251		}
252		return error;
253	}
