255	double Test::print_empirical_threshold(const std::vector<double>& ref,
256	                                       const std::function<std::vector<double>()>& histogram) {
257	
258		constexpr uint32_t runs = 10000;
259	
260		std::vector<double> errors;
261		for (uint32_t n = 0; n < runs; n++) {
262			auto hist = histogram();
263			errors.push_back(Test::total_squared_error(hist, ref));
264		}
265	
266		std::sort(errors.begin(), errors.end(), std::greater<double>());
267	
268		log("\n\t0.1%% of runs had total squared error greater than: " +
269		    std::to_string(errors[runs / 1000]) + "\n\t");
270	
271		return errors[runs / 1000];
272	}
