358		if (a.hit != b.hit) {
359			return "Hit booleans do not match!";
360		}
361	
362		// check other values if there was a hit
363		if (a.hit) {
364			if (differs(a.origin, b.origin)) {
365				return "Hit origins do not match!";
366			}
367			if (std::abs(a.distance - b.distance) > EPS_F) {
368				return "Hit distances do not match!";
369			}
370			if (differs(a.position, b.position)) {
371				return "Hit positions do not match!";
372			}
