466	std::optional<std::string> Test::differs(Halfedge_Mesh const &source, Halfedge_Mesh const &target, CheckExtra check_extra) {
467		//NOTE: check_extra actually ignored for now. Will update!
468	
469		constexpr float epsilon = 0.001f;
470	
471		using HalfedgeCRef = Halfedge_Mesh::HalfedgeCRef;
472		using VertexCRef = Halfedge_Mesh::VertexCRef;
473		using EdgeCRef = Halfedge_Mesh::EdgeCRef;
474		using FaceCRef = Halfedge_Mesh::FaceCRef;
475	
476		Quantized_Vertices source_verts(epsilon);
477		for (VertexCRef v = source.vertices.begin(); v != source.vertices.end(); v++) {
478			source_verts.insert(v->position, v->id);
479		}
480	
481		Quantized_Vertices target_verts(epsilon);
482		for (VertexCRef v = target.vertices.begin(); v != target.vertices.end(); v++) {
483			target_verts.insert(v->position, v->id);
484		}
485	
486		if (!source_verts.all_unique())
487			return "Source mesh does not have epsilon-unique vertex positions.";
488		if (!target_verts.all_unique())
489			return "Target mesh does not have epsilon-unique vertex positions.";
490	
491		std::unordered_map<uint32_t, VertexCRef> v_source_to_target;
492		std::unordered_map<uint32_t, VertexCRef> v_target_to_source;
493	
494		for (VertexCRef v = source.vertices.begin(); v != source.vertices.end(); v++) {
495			if (auto target_id = target_verts.find(v->position)) {
496				v_target_to_source.insert({*target_id, v});
497			} else {
498				return "Source vertex set is not a subset of target vertex set!";
499			}
500		}
501	
502		for (VertexCRef v = target.vertices.begin(); v != target.vertices.end(); v++) {
503			if (auto source_id = source_verts.find(v->position)) {
504				v_source_to_target.insert({*source_id, v});
505			} else {
506				return "Target vertex set is not a subset of source vertex set!";
507			}
508		}
509	
510		// Edges are a bit more complicated because they're not necessarily unique: there can be
511		// multiple edges across the same vertices. Hence we need to make sure to only
512		// use each superset edge once when matching the subset.
513	
514		std::unordered_set<uint32_t> e_target_ids;
515		std::unordered_set<uint32_t> e_source_ids;
516	
517		for (EdgeCRef e = source.edges.begin(); e != source.edges.end(); e++) {
518	
519			uint32_t id0 = e->halfedge->vertex->id;
520			uint32_t id1 = e->halfedge->twin->vertex->id;
521			VertexCRef v0 = v_source_to_target.at(id0);
522			VertexCRef v1 = v_source_to_target.at(id1);
523	
524			bool found = false;
525			HalfedgeCRef h = v0->halfedge;
526			do {
527				if (h->twin->vertex == v1) {
528					auto match = h->edge;
529					if (e_target_ids.find(match->id) == e_target_ids.end()) {
530						found = true;
531						e_target_ids.insert(match->id);
532						break;
533					}
534				}
535				h = h->twin->next;
536			} while (h != v0->halfedge);
537	
538			if (!found) return "Source edge set is not a subset of target edge set!";
539		}
540	
541		for (EdgeCRef e = target.edges.begin(); e != target.edges.end(); e++) {
542	
543			uint32_t id0 = e->halfedge->vertex->id;
544			uint32_t id1 = e->halfedge->twin->vertex->id;
545			VertexCRef v0 = v_target_to_source.at(id0);
546			VertexCRef v1 = v_target_to_source.at(id1);
547	
548			bool found = false;
549			HalfedgeCRef h = v0->halfedge;
550			do {
551				if (h->twin->vertex == v1) {
552					auto match = h->edge;
553					if (e_source_ids.find(match->id) == e_source_ids.end()) {
554						found = true;
555						e_source_ids.insert(match->id);
556						break;
557					}
558				}
559				h = h->twin->next;
560			} while (h != v0->halfedge);
561	
562			if (!found) return "Target edge set is not a subset of source edge set!";
563		}
564	
565		assert(e_source_ids.size() == source.edges.size());
566		assert(e_target_ids.size() == target.edges.size());
567		assert(e_source_ids.size() == e_target_ids.size());
568	
569		// There can also be multiple faces spanning the same vertex set, so we also need
570		// to not re-use face IDs.
571		// Also remember to check face boundary flags.
572	
573		std::unordered_set<uint32_t> f_target_ids;
574		std::unordered_set<uint32_t> f_source_ids;
575	
576		for (FaceCRef f = source.faces.begin(); f != source.faces.end(); f++) {
577	
578			std::unordered_multiset<VertexCRef> verts;
579			{
580				HalfedgeCRef h = f->halfedge;
581				do {
582					verts.insert(v_source_to_target.at(h->vertex->id));
583					h = h->next;
584				} while (h != f->halfedge);
585			}
586	
587			bool found = false;
588			HalfedgeCRef begin = (*verts.begin())->halfedge;
589			HalfedgeCRef h = begin;
590			do {
591				FaceCRef match = h->face;
592	
593				std::unordered_multiset<VertexCRef> remaining_verts = verts;
594				HalfedgeCRef h_match = match->halfedge;
595				do {
596					auto v = remaining_verts.find(h_match->vertex);
597					if (v != remaining_verts.end()) remaining_verts.erase(v);
598					h_match = h_match->next;
599				} while (h_match != match->halfedge);
600	
601				if (remaining_verts.empty() && f_target_ids.find(match->id) == f_target_ids.end() &&
602				    match->boundary == f->boundary) {
603					found = true;
604					f_target_ids.insert(match->id);
605					break;
606				}
607	
608				h = h->twin->next;
609			} while (h != begin);
610	
611			if (!found) return "Source face set is not a subset of target face set!";
612		}
613	
614		for (FaceCRef f = target.faces.begin(); f != target.faces.end(); f++) {
615	
616			std::unordered_multiset<VertexCRef> verts;
617			{
618				HalfedgeCRef h = f->halfedge;
619				do {
620					verts.insert(v_target_to_source.at(h->vertex->id));
621					h = h->next;
622				} while (h != f->halfedge);
623			}
624	
625			bool found = false;
626			HalfedgeCRef begin = (*verts.begin())->halfedge;
627			HalfedgeCRef h = begin;
628			do {
629				FaceCRef match = h->face;
630	
631				std::unordered_multiset<VertexCRef> remaining_verts = verts;
632				HalfedgeCRef h_match = match->halfedge;
633				do {
634					auto v = remaining_verts.find(h_match->vertex);
635					if (v != remaining_verts.end()) remaining_verts.erase(v);
636					h_match = h_match->next;
637				} while (h_match != match->halfedge);
638	
639				if (remaining_verts.empty() && f_source_ids.find(match->id) == f_source_ids.end() &&
640				    match->boundary == f->boundary) {
641					found = true;
642					f_source_ids.insert(match->id);
643					break;
644				}
645	
646				h = h->twin->next;
647			} while (h != begin);
648	
649			if (!found) return "Target face set is not a subset of source face set!";
650		}
651	
652		assert(f_source_ids.size() == source.faces.size());
653		assert(f_target_ids.size() == target.faces.size());
654		assert(f_source_ids.size() == f_target_ids.size());
655	
656		return std::nullopt;
657	}
