724	bool Test::distant_from(const Halfedge_Mesh& from, const Halfedge_Mesh& to, float scale) {
725	
726		for (auto v = to.vertices.begin(); v != to.vertices.end(); ++v) {
727	
728			// This is highly approximate: we simply scale up the threshold by the mean edge length
729			// incident from this vertex. This should make the distance test roughly scale-independent,
730			// but we still need to manually adjust the scale parameter for specific tests.
731	
732			uint32_t n = 0;
733			float avg_edge = 0.0f;
734			auto h = v->halfedge;
735			do {
736				n++;
737				avg_edge += (h->twin->vertex->position - v->position).norm();
738				h = h->twin->next;
739			} while (h != v->halfedge);
740			avg_edge /= static_cast<float>(n);
741	
742			if (closest_distance(from, v->position) > avg_edge * scale * 0.1f) {
743				return true;
744			}
745		}
746	
747		return false;
748	}
