750	float Test::closest_distance(const Halfedge_Mesh& from, const Vec3& to) {
751		float d = std::numeric_limits<float>::infinity();
752	
753		// https://iquilezles.org/articles/triangledistance/
754		auto length2 = [](Vec3 v) { return dot(v, v); };
755		auto distance_to_triangle = [length2](Vec3 p, Vec3 v1, Vec3 v2, Vec3 v3) {
756			Vec3 v21 = v2 - v1;
757			Vec3 p1 = p - v1;
758			Vec3 v32 = v3 - v2;
759			Vec3 p2 = p - v2;
760			Vec3 v13 = v1 - v3;
761			Vec3 p3 = p - v3;
762			Vec3 nor = cross(v21, v13);
763			return std::sqrt(
764				(sign(dot(cross(v21, nor), p1)) + sign(dot(cross(v32, nor), p2)) +
765			         sign(dot(cross(v13, nor), p3)) <
766			     2.0f)
767					? std::min(std::min(length2(v21 * std::clamp(dot(v21, p1) / length2(v21), 0.0f, 1.0f) - p1),
768			                            length2(v32 * std::clamp(dot(v32, p2) / length2(v32), 0.0f, 1.0f) - p2)),
769			                   length2(v13 * std::clamp(dot(v13, p3) / length2(v13), 0.0f, 1.0f) - p3))
770					: dot(nor, p1) * dot(nor, p1) / length2(nor));
771		};
772	
773		for (Halfedge_Mesh::FaceCRef face = from.faces.begin(); face != from.faces.end(); ++face) {
774			if (face->boundary) continue;
775			Halfedge_Mesh::HalfedgeCRef h = face->halfedge;
776			Vec3 v1 = h->vertex->position;
777			h = h->next;
778			do {
779				Vec3 v2 = h->vertex->position;
780				h = h->next;
781				Vec3 v3 = h->vertex->position;
782				d = std::min(d, distance_to_triangle(to, v1, v2, v3));
783			} while (h != face->halfedge);
784		}
785	
786		return d;
787	}
